// Resolve model name from datatable lookup
// Datatable is the single source of truth for model IDs
// Detects haiku/sonnet/opus keyword from caller, maps to datatable value
// Falls back to haiku if no keyword match

const startData = $('Start').item.json;
const modelParam = (startData.model || '').toLowerCase();

// Datatable identifier → keyword mapping
const IDENTIFIER_MAP = {
  'agentcore-haiku-model': 'haiku',
  'agentcore-sonnet-model': 'sonnet',
  'agentcore-opus-model': 'opus'
};

// Build lookup from datatable rows: { haiku: '...', sonnet: '...', opus: '...' }
const modelLookup = {};
const dtRows = $('Get Model Config').all();
for (const row of dtRows) {
  const id = row.json.identifier;
  const val = row.json.value;
  if (id && val && IDENTIFIER_MAP[id]) {
    modelLookup[IDENTIFIER_MAP[id]] = val;
  }
}

// Detect keyword in model param, default to haiku
let resolvedModel;
if (modelParam.includes('opus')) {
  resolvedModel = modelLookup.opus;
} else if (modelParam.includes('sonnet')) {
  resolvedModel = modelLookup.sonnet;
} else {
  resolvedModel = modelLookup.haiku;
}

// Pass through all original Start data with resolved model
return [{ json: { ...startData, resolved_model: resolvedModel } }];

