// Generic LLM response parser
// Returns { llm_response: parsedJson } on success
// Throws error with raw response on failure (for debugging)

const httpResponse = $input.first().json;
const startData = $('Start').item.json;
const nodeName = startData.node_name || 'Unknown';

// Repair unescaped quotes inside JSON string values.
// When JSON.parse fails at a position, find the problematic quote,
// look ahead for its matching closing quote, and escape both.
// Repeats up to 50 times for multiple occurrences.
function repairUnescapedQuotes(str) {
  let repaired = str;
  for (let attempt = 0; attempt < 50; attempt++) {
    try {
      return JSON.parse(repaired);
    } catch (e) {
      const match = e.message.match(/position\s+(\d+)/);
      if (!match) return null;
      const pos = parseInt(match[1]);
      if (pos <= 0 || pos >= repaired.length) return null;
      let quotePos = -1;
      if (repaired[pos - 1] === '"' && (pos < 2 || repaired[pos - 2] !== '\\')) {
        quotePos = pos - 1;
      } else if (repaired[pos] === '"' && (pos < 1 || repaired[pos - 1] !== '\\')) {
        quotePos = pos;
      }
      if (quotePos === -1) return null;
      let closePos = -1;
      for (let i = quotePos + 1; i < repaired.length; i++) {
        if (repaired[i] === '"' && repaired[i - 1] !== '\\') {
          const after = repaired[i + 1];
          if (after && after !== ',' && after !== '}' && after !== ']' && after !== ':') {
            closePos = i;
            break;
          }
          break;
        }
      }
      if (closePos !== -1) {
        repaired = repaired.substring(0, closePos) + '\\"' + repaired.substring(closePos + 1);
        repaired = repaired.substring(0, quotePos) + '\\"' + repaired.substring(quotePos + 1);
      } else {
        repaired = repaired.substring(0, quotePos) + '\\"' + repaired.substring(quotePos + 1);
      }
    }
  }
  return null;
}

// Robust JSON parsing function - handles various LLM response formats
function parseJsonRobust(response) {
  if (!response) return null;

  let cleaned = typeof response === 'string' ? response : String(response);
  cleaned = cleaned.trim();

  // Try 1: Parse as-is
  try { return JSON.parse(cleaned); } catch (e) {}

  // Try 2: Remove markdown code fences with json identifier (handles ```json [line 86] etc)
  if (cleaned.startsWith('```json')) {
    const withoutFences = cleaned.replace(/^```json[^\n]*\n?/, '').replace(/\n?```\s*$/, '').trim();
    try { return JSON.parse(withoutFences); } catch (e) {}
  }

  // Try 3: Remove generic markdown code fences
  if (cleaned.startsWith('```')) {
    const withoutFences = cleaned.replace(/^```[^\n]*\n?/, '').replace(/\n?```\s*$/, '').trim();
    try { return JSON.parse(withoutFences); } catch (e) {}
  }

  // Try 4: Find JSON block between any code fences (handles annotations like [line X])
  const codeBlockMatch = cleaned.match(/```(?:json)?[^\n]*\n?([\s\S]*?)\n?```/);
  if (codeBlockMatch && codeBlockMatch[1]) {
    try { return JSON.parse(codeBlockMatch[1].trim()); } catch (e) {}
  }

  // Try 5: Remove common prefixes
  const prefixPatterns = [/^Here's the JSON:?\s*/i, /^Here is the JSON:?\s*/i, /^JSON:?\s*/i, /^Response:?\s*/i, /^Output:?\s*/i, /^Result:?\s*/i];
  for (const pattern of prefixPatterns) {
    if (pattern.test(cleaned)) {
      const withoutPrefix = cleaned.replace(pattern, '').trim();
      try { return JSON.parse(withoutPrefix); } catch (e) {
        const withoutFences = withoutPrefix.replace(/^```(?:json)?[^\n]*\n?/, '').replace(/\n?```\s*$/, '').trim();
        try { return JSON.parse(withoutFences); } catch (e2) {}
      }
    }
  }

  // Try 6: Extract JSON from surrounding text (most permissive - find first { or [ to last } or ])
  const jsonStartBrace = cleaned.indexOf('{');
  const jsonStartBracket = cleaned.indexOf('[');
  const jsonStart = jsonStartBrace !== -1 && jsonStartBracket !== -1 ? Math.min(jsonStartBrace, jsonStartBracket) : Math.max(jsonStartBrace, jsonStartBracket);
  const jsonEndBrace = cleaned.lastIndexOf('}');
  const jsonEndBracket = cleaned.lastIndexOf(']');
  const jsonEnd = jsonEndBrace !== -1 && jsonEndBracket !== -1 ? Math.max(jsonEndBrace, jsonEndBracket) : Math.max(jsonEndBrace, jsonEndBracket);

  if (jsonStart !== -1 && jsonEnd !== -1 && jsonEnd > jsonStart) {
    const extracted = cleaned.substring(jsonStart, jsonEnd + 1);
    try { return JSON.parse(extracted); } catch (e) {
      // Try fixing common JSON issues
      const fixed = extracted.replace(/,\s*}/g, '}').replace(/,\s*]/g, ']').replace(/([{,]\s*)(\w+)(\s*:)/g, '$1"$2"$3');
      try { return JSON.parse(fixed); } catch (e2) {}
    }
  }

  // Try 7: Repair unescaped quotes inside string values (e.g. LLM writes "In Other Shoes" unescaped)
  const candidate = jsonStart !== -1 && jsonEnd !== -1 ? cleaned.substring(jsonStart, jsonEnd + 1) : cleaned;
  const repaired = repairUnescapedQuotes(candidate);
  if (repaired) return repaired;

  return null;
}

// Check HTTP Status
if (httpResponse.statusCode && httpResponse.statusCode >= 400) {
  throw new Error(`[${nodeName}] HTTP ${httpResponse.statusCode}: ${httpResponse.body?.error || 'No details'}`);
}

// Extract agent_response
let agentResponse = httpResponse.body?.agent_response || httpResponse.agent_response || httpResponse.body?.response || httpResponse.response;
if (!agentResponse && typeof httpResponse.body === 'string') agentResponse = httpResponse.body;

if (!agentResponse) {
  if (httpResponse.body?.error) throw new Error(`[${nodeName}] API error: ${httpResponse.body.error}`);
  throw new Error(`[${nodeName}] No agent_response in HTTP response. Keys: ${Object.keys(httpResponse.body || {}).join(', ')}`);
}

// Parse JSON
const parsedJson = parseJsonRobust(agentResponse);
if (!parsedJson) {
  // Include raw LLM response in error for debugging
  throw new Error(`[${nodeName}] JSON parse failed. Raw response: ${String(agentResponse).substring(0, 500)}`);
}

parsedJson.token_usage = $input.first().json.body.usage;
// Return wrapped in llm_response key (no validation, no merging)
return [{ json: { llm_response: parsedJson } }];

